static final class Fake implements ProcessRunner {
    volatile boolean holdScan;
    volatile boolean scanning;
    volatile boolean released;
    @Override public Result run(List<String> command, Duration timeout) {
        if (command.getFirst().equals("ssh-keyscan")) {
            scanning = true;
            if (holdScan) await(() -> released);
            return new Result(0, KEY_LINE + "\n", "");
        }
        return new Result(0, "", "");
    }
    @Override public RunningProcess start(List<String> command) {
        return new RunningProcess() { public boolean isAlive() { return true; } public void close() {} };
    }
}
```

